<?php
namespace App\Http\Controllers\Tenant;
use App\Http\Controllers\Controller; use App\Models\User; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash;
class StaffController extends Controller { public function index(){return view('tenant.staff',['users'=>User::where('agency_id',auth()->user()->agency_id)->latest()->get()]);} public function store(Request $r){$a=auth()->user()->agency;$limit=$a->plan?->user_limit;if($limit && $a->users()->count()>=$limit) return back()->withErrors(['plan' => __('Your plan user limit has been reached.')]);$d=$r->validate(['name'=>'required|max:120','email'=>'required|email|unique:users,email','password'=>'required|min:8','role'=>'required|in:agency_manager,agent,accountant,cashier,data_entry,viewer','locale'=>'required|in:en,fa,ps']);User::create($d+['agency_id'=>$a->id,'password'=>Hash::make($d['password']),'is_active'=>1]);return back()->with('success', __('Staff user created.'));} public function toggle(User $user){abort_unless($user->agency_id===auth()->user()->agency_id,403);abort_if($user->id===auth()->id(),422,__('You cannot disable your own account.'));$user->update(['is_active'=>!$user->is_active]);return back();} }
